class PanelQuad;

typedef PanelQuad *(*GetPointerFunction)(void *, const char *);
struct GetPointerSlot
{
    short adjustment;
    unsigned short padding;
    GetPointerFunction function;
};
struct FEMenuVTable
{
    char padding[0x198];
    GetPointerSlot get_pointer;
};
struct FEMenuParent
{
    FEMenuVTable *vtable;
};

typedef void (*TurnOnFunction)(void *, bool);
struct TurnOnSlot
{
    short adjustment;
    unsigned short padding;
    TurnOnFunction function;
};
struct PanelQuadVTable
{
    char padding[0x18];
    TurnOnSlot turn_on;
};
class PanelQuad
{
    char padding[0x194];
    PanelQuadVTable *vtable;

public:
    void TurnOn(bool on)
    {
        TurnOnSlot &slot = vtable->turn_on;
        slot.function((char *)this + slot.adjustment, on);
    }
};

class TrickBookFrontEnd
{
    char padding_to_parent[0x74];
    FEMenuParent *parent;
    char padding_to_arrows[0x18C - 0x78];
    PanelQuad *arrows[2][2];
    PanelQuad *bkg;

    PanelQuad *GetPointer(const char *name)
    {
        GetPointerSlot &slot = parent->vtable->get_pointer;
        return slot.function((char *)this + slot.adjustment, name);
    }

public:
    void SetPQIndices();
};

void TrickBookFrontEnd::SetPQIndices()
{
	arrows[0][0] = GetPointer("button_off_01");
	arrows[0][1] = GetPointer("button_on_01");
	arrows[1][0] = GetPointer("button_off_02");
	arrows[1][1] = GetPointer("button_on_02");

	arrows[0][1]->TurnOn(false);
	arrows[1][1]->TurnOn(false);

	bkg = GetPointer("trickbook_window");
	bkg->TurnOn(false);	// drawn separately
}
